"use strict";(globalThis.webpackChunkshillinq_docs=globalThis.webpackChunkshillinq_docs||[]).push([[2256],{7674(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Shillinq","docId":"intro","unlisted":false},{"type":"category","label":"Tutorials","collapsible":true,"collapsed":false,"items":[{"type":"category","label":"User guide","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/docs/tutorials/user/first-launch","label":"Open Shillinq for the first time","docId":"tutorials/user/first-launch","unlisted":false},{"type":"link","href":"/docs/tutorials/user/send-invoice","label":"Send your first invoice","docId":"tutorials/user/send-invoice","unlisted":false},{"type":"link","href":"/docs/tutorials/user/record-bill","label":"Record a supplier bill","docId":"tutorials/user/record-bill","unlisted":false},{"type":"link","href":"/docs/tutorials/user/create-purchase-order","label":"Create a purchase order","docId":"tutorials/user/create-purchase-order","unlisted":false},{"type":"link","href":"/docs/tutorials/user/bank-reconciliation","label":"Reconcile a bank statement","docId":"tutorials/user/bank-reconciliation","unlisted":false},{"type":"link","href":"/docs/tutorials/user/manage-contract","label":"Manage a contract","docId":"tutorials/user/manage-contract","unlisted":false},{"type":"link","href":"/docs/tutorials/user/vat-return","label":"Prepare a VAT return","docId":"tutorials/user/vat-return","unlisted":false},{"type":"link","href":"/docs/tutorials/user/financial-statements","label":"Read your financial statements","docId":"tutorials/user/financial-statements","unlisted":false}],"href":"/docs/category/user-guide"},{"type":"category","label":"Admin guide","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/tutorials/admin/chart-of-accounts","label":"Set up your chart of accounts","docId":"tutorials/admin/chart-of-accounts","unlisted":false},{"type":"link","href":"/docs/tutorials/admin/approval-chains","label":"Configure supplier approval chains","docId":"tutorials/admin/approval-chains","unlisted":false},{"type":"link","href":"/docs/tutorials/admin/admin-settings","label":"Manage Shillinq settings","docId":"tutorials/admin/admin-settings","unlisted":false}],"href":"/docs/category/admin-guide"}],"href":"/docs/category/tutorials"},{"type":"link","href":"/docs/ARCHITECTURE","label":"Shillinq \u2014 Architecture","docId":"ARCHITECTURE","unlisted":false},{"type":"link","href":"/docs/FEATURES","label":"Shillinq \u2014 Feature Analysis","docId":"FEATURES","unlisted":false}]},"docs":{"ARCHITECTURE":{"id":"ARCHITECTURE","title":"Shillinq \u2014 Architecture","description":"Complete open-source business administration suite for freelancers, sole proprietors, SMBs, and corporations. Combines bookkeeping, invoicing, procurement, and contract management into one self-hosted solution on Nextcloud.Named after the shilling \u2014 one of the oldest and most widely used coins in European history, from the Roman solidus to the British shilling to the East African shilling still in use today.Shillinq covers:- Bookkeeping & general ledger (double-entry accounting)- Accounts payable & receivable- Sales invoicing & e-invoicing (UBL/Peppol)- Purchase orders & procurement workflows- Supplier management & approval chains- Contract lifecycle management (creation, renewal, obligations)- Bank reconciliation & payment matching- VAT/tax reporting & compliance- Financial statements (P&L, balance sheet, cash flow)- Budget planning & forecasting- Multi-currency support- Dutch government compliance (BBV, IV3, SiSa, DigiInkoop)","sidebar":"tutorialSidebar"},"FEATURES":{"id":"FEATURES","title":"Shillinq \u2014 Feature Analysis","description":"Competitors (20)","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Shillinq","description":"Complete open-source business administration suite for freelancers, sole","sidebar":"tutorialSidebar"},"tutorials/admin/admin-settings":{"id":"tutorials/admin/admin-settings","title":"Manage Shillinq settings","description":"Open Shillinq\'s admin settings, confirm the version, point at the OpenRegister register, and import schemas so every list view loads.","sidebar":"tutorialSidebar"},"tutorials/admin/approval-chains":{"id":"tutorials/admin/approval-chains","title":"Configure supplier approval chains","description":"Set the amount bands and the approver(s) per band \u2014 Shillinq routes each bill and PO through the right chain automatically.","sidebar":"tutorialSidebar"},"tutorials/admin/chart-of-accounts":{"id":"tutorials/admin/chart-of-accounts","title":"Set up your chart of accounts","description":"Pick (or import) a chart of accounts, map it to RGS / BBV, and configure VAT rates so every invoice and bill posts to the right place.","sidebar":"tutorialSidebar"},"tutorials/user/bank-reconciliation":{"id":"tutorials/user/bank-reconciliation","title":"Reconcile a bank statement","description":"Import a CAMT.053 bank statement, let Shillinq match transactions to invoices and bills, and close out the unmatched lines.","sidebar":"tutorialSidebar"},"tutorials/user/create-purchase-order":{"id":"tutorials/user/create-purchase-order","title":"Create a purchase order","description":"Raise a PO to a supplier, route it for approval, send it, and use it to three-way-match the supplier\'s bill when it arrives.","sidebar":"tutorialSidebar"},"tutorials/user/financial-statements":{"id":"tutorials/user/financial-statements","title":"Read your financial statements","description":"Generate the P&L, balance sheet, and cash-flow statement for a period \u2014 drill into a line, export to SBR / XBRL or PDF.","sidebar":"tutorialSidebar"},"tutorials/user/first-launch":{"id":"tutorials/user/first-launch","title":"Open Shillinq for the first time","description":"Open Shillinq, find your way around the dashboard, and confirm the OpenRegister back end is connected.","sidebar":"tutorialSidebar"},"tutorials/user/manage-contract":{"id":"tutorials/user/manage-contract","title":"Manage a contract","description":"Create a supplier or customer contract \u2014 track obligations, get a heads-up before auto-renewal, and tie POs and invoices back to it.","sidebar":"tutorialSidebar"},"tutorials/user/record-bill":{"id":"tutorials/user/record-bill","title":"Record a supplier bill","description":"Capture a supplier invoice, attach the PDF, code the lines, route it for approval, and schedule the payment.","sidebar":"tutorialSidebar"},"tutorials/user/send-invoice":{"id":"tutorials/user/send-invoice","title":"Send your first invoice","description":"Create a sales invoice, add line items with VAT, render it as a UBL/Peppol e-invoice, and send it to the customer.","sidebar":"tutorialSidebar"},"tutorials/user/vat-return":{"id":"tutorials/user/vat-return","title":"Prepare a VAT return","description":"Roll up the quarter\'s VAT into a Belastingdienst-format aangifte omzetbelasting \u2014 review the boxes, file it via SBR / Digipoort, and post the settlement.","sidebar":"tutorialSidebar"}}}}')}}]);